Environments.EnvironmentViewMatchesEnvir.source:
(m) =>
			[
				m.Environment.every((e) => {
					const view = m.EnvironmentView.find((v) => v.id === e.id)
					if (e.state.status === "" || e.state.status === "deleted") {
						return view === undefined
					}
					if (view === undefined) {
						return false
					}
					return [
						view.state.id === e.id,
						view.state.version === e.state.version,
						view.state.name === e.state.name,
						!!view.state.archived_at === (e.state.status === "archived"),
					].every((ok) => ok)
				}),
				m.EnvironmentView.every((v) =>
					m.Environment.some((e) =>
						[e.id === v.id, e.state.status !== "", e.state.status !== "deleted"].every((ok) => ok),
					),
				),
			].every((ok) => ok)

Environment.UpdateKeepsWhatItDoesNotName.source:
({ before, after, command }) => {
			if (command._tag !== "UpdateEnvironment") {
				return true
			}
			if (after.config === null || before.config === null) {
				return false
			}
			const kept = after.config.networking
			const asked =
				command.changes.config === undefined
					? before.config.networking
					: command.changes.config.networking
			return [
				after.name === (command.changes.name === undefined ? before.name : command.changes.name),
				after.description ===
					(command.changes.description === undefined
						? before.description
						: command.changes.description),
				kept.type === asked.type,
				kept.type !== "limited" ||
					asked.type !== "limited" ||
					(kept.allow_mcp_servers === asked.allow_mcp_servers &&
						kept.allow_package_managers === asked.allow_package_managers),
			].every((ok) => ok)
		}

Environments.EnvironmentViewConfigMatche.source:
(m) =>
			m.Environment.every((e) => {
				const view = m.EnvironmentView.find((v) => v.id === e.id)
				if (view === undefined) {
					return true
				}
				if (e.state.config === null) {
					return false
				}
				const projected = view.state.config.networking
				const committed = e.state.config.networking
				return [
					view.state.description === e.state.description,
					projected.type === committed.type,
					projected.type !== "limited" ||
						committed.type !== "limited" ||
						(projected.allow_mcp_servers === committed.allow_mcp_servers &&
							projected.allow_package_managers === committed.allow_package_managers &&
							projected.allowed_hosts.length === committed.allowed_hosts.length &&
							projected.allowed_hosts.every(
								(host, index) => host === committed.allowed_hosts[index],
							)),
				].every((ok) => ok)
			})
